def main():
    target_files = [
        'w09-d01.json', 'w09-d02.json', 'w09-d03.json', 'w09-d04.json', 'w09-d05.json',
        'w10-d01.json', 'w10-d02.json', 'w10-d03.json', 'w10-d04.json', 'w10-d05.json'
    ]

    updated_count = 0
    total_questions = 0

    for filename in target_files:
        filepath = os.path.join(DATA_DIR, filename)
        if not os.path.exists(filepath):
            print(f"❌ File not found: {filepath}")
            continue

        with open(filepath, 'r', encoding='utf-8') as f:
            data = json.load(f)

        for q in data.get('questions', []):
            total_questions += 1
            track_id = q.get('trackId')
            if track_id in SCRIPTS:
                q['script'] = SCRIPTS[track_id]
                updated_count += 1
            else:
                print(f"⚠️  Missing script for {track_id} in {filename}")

        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)

        print(f"✓ Updated {filename} ({len(data.get('questions', []))} questions)")

    print(f"\n✅ Total questions updated: {updated_count}/{total_questions}")
    assert updated_count == 60, f"Expected 60 updated questions, got {updated_count}"
    print("🎉 All 60 scripts successfully updated!")

if __name__ == '__main__':
    main()
